"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2651],{62651:e=>{e.exports=JSON.parse('{"slug":"uyazvimost-php2shell-sayty-bankov-oktyabr-2026","locale":"es","title":"El FSB ordena desconectar webs bancarias y p\xfablicas sin actualizar ante fallos de PHP","description":"Dos vulnerabilidades cr\xedticas de PHP obligan a bancos y organismos p\xfablicos a actualizar o cerrar sus webs. Por qu\xe9 un fallo afecta a tantos servicios.","blocks":[{"id":"b001","kind":"paragraph","text":"Los desarrolladores de PHP publicaron el 21 de octubre correcciones de dos vulnerabilidades llamadas PHP2Shell, ambas con gravedad de 9,2 sobre 10. Un atacante puede ejecutar c\xf3digo y acceder a datos con una petici\xf3n sin contrase\xf1a. Los detalles iban a publicarse m\xe1s tarde, pero se filtraron. Un se\xf1uelo de Amazon detect\xf3 el primer intento el 17 de octubre, 4 d\xedas antes del parche. Wiz cree que los fallos llevan d\xe9cadas presentes y que la IA ayud\xf3 a convertirlos en un ataque funcional."},{"id":"b002","kind":"paragraph","text":"El 22 de octubre, el centro nacional de incidentes inform\xe1ticos del FSB envi\xf3 mediante GosSOPKA una circular a infraestructuras cr\xedticas: administraci\xf3n, finanzas, energ\xeda, transporte y salud. Ordena actualizar PHP y analizar los servidores con antivirus. Si no pueden hacerlo pronto, deben limitar el acceso externo o desconectarlos."},{"id":"b003","kind":"paragraph","text":"Imagina una ciudad donde casi todos los portales usan una marca de cerradura. Se descubre una llave universal y ya circulan copias. Todos deben cambiarlas; mientras llega el t\xe9cnico, conviene mantener cerrado desde dentro. Es riesgo sist\xe9mico: una soluci\xf3n com\xfan hace que un fallo golpee a todos. PHP es gratuito y c\xf3modo, por eso sostiene buena parte de internet y un error se vuelve colectivo."},{"id":"b004","kind":"paragraph","text":"Otros pa\xedses ya cerraron sitios. Reino Unido suspendi\xf3 32 servicios p\xfablicos como precauci\xf3n durante la actualizaci\xf3n. Tambi\xe9n hubo webs p\xfablicas inaccesibles en B\xe9lgica, Pa\xedses Bajos, Finlandia, Francia y Alemania. Las empresas de seguridad informan de millones de intentos. No hay a\xfan datos de cierres o intrusiones masivas en Rusia."},{"id":"b005","kind":"paragraph","text":"La web de un banco, organismo o \xe1rea personal puede dejar de abrir temporalmente. Eso no demuestra una intrusi\xf3n: puede estar instal\xe1ndose el parche. Para la empresa, parar cuesta ventas y confianza; una intrusi\xf3n cuesta m\xe1s: datos filtrados, multas, dinero robado y reconstrucci\xf3n. Por eso se elige una parada breve."},{"id":"b006","kind":"paragraph","text":"El plazo depende de cada entidad. Un gran banco con procesos maduros puede actualizar en horas; peque\xf1as empresas o versiones antiguas sin soporte pueden seguir expuestas. Los ataques exitosos se conocer\xe1n al revisar registros. Los cortes breves de estos d\xedas suelen indicar mantenimiento; m\xe1s peligroso es un servidor vulnerable que funciona como si nada."},{"id":"b007","kind":"heading","text":"\xbfQu\xe9 es PHP2Shell?"},{"id":"b008","kind":"paragraph","text":"Son dos fallos de PHP, CVE-2026-109618 y CVE-2026-109619, con gravedad de 9,2 sobre 10. Permiten ejecutar c\xf3digo y acceder a datos con una petici\xf3n sin contrase\xf1a. El parche sali\xf3 el 21 de octubre de 2026."},{"id":"b009","kind":"heading","text":"\xbfDejar\xe1n de funcionar bancos y webs p\xfablicas?"},{"id":"b010","kind":"paragraph","text":"Puede ocurrir durante la actualizaci\xf3n. El 22 de octubre, el centro del FSB orden\xf3 a infraestructuras cr\xedticas, incluidos bancos y administraciones, actualizar PHP o limitar y cerrar el acceso si no era posible. No hay datos de una interrupci\xf3n masiva en Rusia."},{"id":"b011","kind":"heading","text":"\xbfPor qu\xe9 un error afecta a tantos sitios?"},{"id":"b012","kind":"paragraph","text":"PHP se usa en cerca del 70% de las webs mundiales y m\xe1s del 90% de las rus\xf3fonas. Con una base com\xfan para millones de sitios, un fallo los expone a la vez y cada propietario debe actualizar."}],"sources":[{"label":"RBC: el FSB recomienda desconectar webs por un fallo de PHP","url":"https://www.kommersant.ru/doc/9045269"},{"label":"El centro del FSB ordena desconectar sitios vulnerables","url":"https://frankmedia.ru/311764"},{"label":"PHP2Shell: vulnerabilidades cr\xedticas corregidas; actualizar ahora","url":"https://www.helpnetsecurity.com/2026/10/21/php2shell-php-vulnerabilities-patched-cve-2026-109618-cve-2026-109619/"},{"label":"PHP2Shell: riesgo de explotaci\xf3n masiva tras la filtraci\xf3n","url":"https://www.securityweek.com/php2shell-mass-exploitation-looms-for-leaked-critical-php-flaws/"},{"label":"Millones de intentos contra webs de todo el mundo por el fallo de PHP","url":"https://www.theguardian.com/technology/2026/oct/22/websites-across-world-hit-by-millions-of-attempts-to-exploit-php-code-flaw"},{"label":"PHP2Shell deja fuera de servicio decenas de servicios p\xfablicos brit\xe1nicos","url":"https://www.theregister.com/security/2026/10/22/php2shell-puts-dozens-of-uk-government-services-out-of-service/5304840"},{"label":"Dos fallos de seguridad web detectados con IA generan alarma mundial","url":"https://www.forbes.ru/tekhnologii/570823-vyavlennye-s-pomos-u-ii-dve-uazvimosti-v-veb-bezopasnosti-vyzvali-trevogu-v-mire"}],"sourceBodySha256":"e3fb2a77720fe8860c329873f043e4f7761ab7ab4c70849c9068a88ee60dd68e"}')}}]);